const [gradeProof, setGradeProof] = useState<Record<string, string>>({});
const [from, setFrom] = useState<Record<string, string>>({});
const [permissions, setPermissions] = useState<Record<string, string>>({});
const [graceDays, setGraceDays] = useState<string | null>(null);
const [entryDate, setEntryDate] = useState<string | null>(null);
const [pot, setPot] = useState<string | null>(null);
const [parent, setParent] = useState<string | null>(null);
const today = useSheetToday(sheetId).data?.today;
const [user, setUser] = useState('');
const [role, setRole] = useState('');

const [delegateUser, setDelegateUser] = useState('');
const [delegateFrom, setDelegateFrom] = useState('');
const [delegateTo, setDelegateTo] = useState('');

const [holidayDate, setHolidayDate] = useState('');
const [voidReason, setVoidReason] = useState('');

const saveOnce = useSingleFlight();
const save = useMutation({
  mutationFn: (f: { clerkLimit: string | null; floor: string | null; terms: string | null; latePct: string | null; policyDate: string | null; periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; from: Record<string, string>; proofThreshold: string | null; noteThreshold: string | null; permissions: Record<string, string>; graceDays: string | null; entryDate: string | null; gradeGrace: Record<string, string>; gradeProofThreshold: Record<string, string>; pot: string | null; parent: string | null }) =>
    postJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, f),
  onSuccess: (saved) => {
    setLimit(null);
    setFloor(null);
    setTerms(null);
    setGradeTerms({});
    setGradeGrace({});
    setGradeProof({});
    setLatePct(null);
    setPolicyDate(null);
    setNumberingFrom(null);
    setCap(null);
    setProofThreshold(null);
    setNoteThreshold(null);
    setFrom({});
    setPermissions({});
    setGraceDays(null);
    setEntryDate(null);
    setPot(null);
    setParent(null);
    queryClient.setQueryData(settingsKey(sheetId), saved);
    // The pot is shared out as the cuts of the balanced pools.
    void queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    // A grade with no rate of its own falls back to the parent sheets' rates.
    void queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
  },
});

const roleOnce = useSingleFlight();
const assign = useMutation({
  mutationFn: (f: { user: string; role: string }) =>
    postJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`, f),
  onSuccess: (saved) => {
    setUser('');
    setRole('');
    queryClient.setQueryData(settingsKey(sheetId), saved);
  },
});

const delegateOnce = useSingleFlight();
return (
  <section data-testid="settings">
    <p>
      Parent sheet: <strong data-testid="sheet-parent">{settings.data?.parent ?? ''}</strong>
    </p>
    <form
      data-testid="settings-form"
      onSubmit={(e) => {
        e.preventDefault();
        saveOnce(() => {
          save.reset();
          return save.mutateAsync({ clerkLimit: limit, floor, terms, latePct, policyDate, periodNumberingFrom: numberingFrom, gradeTerms, cap, from, proofThreshold, noteThreshold, permissions, graceDays, entryDate, gradeGrace, gradeProofThreshold: gradeProof, pot, parent });
        });
      }}
    >
      <label>
        Clerk limit{' '}
        <input
          data-testid="setting-clerk-limit"
          inputMode="decimal"
          value={limit ?? ''}
          value={entryDate ?? ''}
          onFocus={() => setEntryDate((v) => v ?? '')}
          onChange={(e) => {
            setEntryDate(e.target.value);
            save.reset();
          }}
        />
      </label>{' '}
      <label>
        Pot{' '}
        <input
          data-testid="setting-pot"
          inputMode="decimal"
          value={pot ?? ''}
          onFocus={() => setPot((v) => v ?? '')}
          onChange={(e) => {
            setPot(e.target.value);
            save.reset();
          }}
        />
      </label>{' '}
      <label>
        Parent sheet{' '}
        <input
          data-testid="setting-parent"
          value={parent ?? ''}
          onFocus={() => setParent((v) => v ?? '')}
          onChange={(e) => {
            setParent(e.target.value);
            save.reset();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="settings-save" disabled={save.isPending}>
        Save settings
      </button>{' '}
      Current: clerk limit <strong data-testid="setting-clerk-limit-current">{settingOn(settings.data, 'clerk-limit', today) ?? ''}</strong>,
      floor <strong data-testid="setting-floor-current">{settingOn(settings.data, 'floor', today) ?? ''}</strong>,
      terms <strong data-testid="setting-terms-current">{settingOn(settings.data, 'terms', today) ?? ''}</strong>,
      {GRADES.map((g) => (
        <span key={g}>
          terms {g} <strong data-testid={`setting-terms-${g}-current`}>{settingOn(settings.data, `terms-${g}`, today) ?? ''}</strong>,{' '}
        </span>
      ))}
      {GRADES.map((g) => (
        <span key={g}>
          grace {g} <strong data-testid={`setting-grace-${g}-current`}>{settingOn(settings.data, `grace-${g}`, today) ?? ''}</strong>,{' '}
        </span>
      ))}
      late % <strong data-testid="setting-late-pct-current">{settingOn(settings.data, 'late-pct', today) ?? ''}</strong>,
      policy date <strong data-testid="setting-policy-date-current">{settings.data?.policyDate ?? ''}</strong>,
      period numbering from{' '}
      <strong data-testid="setting-period-numbering-from-current">{settings.data?.periodNumberingFrom ?? ''}</strong>,
      cap <strong data-testid="setting-cap-current">{settingOn(settings.data, 'cap', today) ?? ''}</strong>,
      proof threshold <strong data-testid="setting-proof-threshold-current">{settingOn(settings.data, 'proof-threshold', today) ?? ''}</strong>,
      {GRADES.map((g) => (
        <span key={g}>
          proof threshold {g} <strong data-testid={`setting-proof-threshold-${g}-current`}>{settingOn(settings.data, `proof-threshold-${g}`, today) ?? ''}</strong>,{' '}
        </span>
      ))}
      note threshold <strong data-testid="setting-note-threshold-current">{settingOn(settings.data, 'note-threshold', today) ?? ''}</strong>
      {PERM_ACTIONS.map((a) => (
        <span key={a}>
          , may {a} <strong data-testid={`setting-perm-${a}-current`}>{settings.data?.permissions?.[a] ?? ''}</strong>
        </span>
      ))}
      , grace days <strong data-testid="setting-grace-days-current">{settings.data?.graceDays ?? ''}</strong>
      , entry date <strong data-testid="setting-entry-date-current">{settings.data?.entryDate ?? ''}</strong>
      , pot <strong data-testid="setting-pot-current">{settings.data?.pot ?? ''}</strong>
      , parent <strong data-testid="setting-parent-current">{settings.data?.parent ?? ''}</strong>
      {save.isError && <p data-testid="settings-error">{save.error.message}</p>}
    </form>
    <form
      data-testid="role-form"
      onSubmit={(e) => {
        e.preventDefault();
        roleOnce(() => {
          assign.reset();
          return assign.mutateAsync({ user, role });
        });
      }}

